// Auto-generated 17^3 3D LUT binary bundles for all camera profiles
export const LUT_SIZE = 17;
export const LUT_DATA_BASE64 = {
  "fuji.classic_chrome_approx": "",
  "fuji.velvia_50_approx": "",
  "fuji.provia_approx": "",
  "fuji.astia_approx": "",
  "fuji.acros_approx": "",
  "kodak.portra_160_approx": "",
  "kodak.portra_400_approx": "",
  "kodak.gold_200_approx": "",
  "kodak.ektar_100_approx": "",
  "kodak.trix_400_approx": "",
  "leica.m_system_approx": "",
  "leica.cl_monochrom_approx": "",
  "leica.street_look_approx": "",
  "hasselblad.hncs_approx": "",
  "sony.fl_approx": "",
  "sony.in_approx": "",
  "sony.scinetone_mobile_approx": ""
};

export function getLutUint8Array(presetId) {
  const b64 = LUT_DATA_BASE64[presetId];
  if (!b64) return null;
  const binary = atob(b64);
  const len = binary.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}
